# Diálogos antes dos chefes das 10:00 e dos Guardiões do Limiar (data/dialogues.json).
# Ordem: pt_BR, en, es, de, fr, ru, id, ja, ko, zh_TW, zh_CN.
STRINGS = {
    # Kappa Ancião (Vila)
    "dialog.kappa_elder.open": ["Esse rosto... a água do arrozal guardou ele por cem anos.", "That face... the paddy water kept it for a hundred years.", "Ese rostro... el agua del arrozal lo guardó cien años.", "Dieses Gesicht... das Wasser der Reisfelder bewahrte es hundert Jahre.", "Ce visage... l'eau de la rizière l'a gardé cent ans.", "Это лицо... вода рисовых полей хранила его сто лет.", "Wajah itu... air sawah menyimpannya seratus tahun.", "その顔……田の水が百年覚えていた。", "그 얼굴... 논물이 백 년 동안 간직했지.", "那張臉……稻田的水守了它一百年。", "那张脸……稻田的水守了它一百年。"],
    "dialog.kappa_elder.reply.aki": ["Você me conhece? Então me diga quem eu era.", "You know me? Then tell me who I was.", "¿Me conoces? Entonces dime quién era yo.", "Du kennst mich? Dann sag mir, wer ich war.", "Tu me connais ? Alors dis-moi qui j'étais.", "Ты меня знаешь? Тогда скажи, кем я была.", "Kau mengenalku? Kalau begitu, katakan siapa aku dulu.", "私を知っているの？なら、私が誰だったか教えて。", "나를 알아? 그럼 내가 누구였는지 말해 줘.", "你認得我？那就告訴我，我曾是誰。", "你认得我？那就告诉我，我曾是谁。"],
    "dialog.kappa_elder.reply.kenta": ["Já vi minha vila marchar. A sua não leva mais ninguém.", "I've seen my village march. Yours takes no one else.", "Ya vi a mi aldea marchar. La tuya no se lleva a nadie más.", "Ich sah mein Dorf marschieren. Deins nimmt niemanden mehr mit.", "J'ai vu mon village marcher. Le tien n'emportera plus personne.", "Я видел, как шагала моя деревня. Твоя больше никого не заберёт.", "Aku sudah melihat desaku berbaris. Desamu tak membawa siapa pun lagi.", "俺の里が行進するのはもう見た。お前にはもう誰も連れて行かせない。", "내 마을이 행진하는 걸 봤다. 네 마을은 더는 아무도 데려가지 못해.", "我見過自己的村子行進。你的村子別想再帶走任何人。", "我见过自己的村子行进。你的村子别想再带走任何人。"],
    "dialog.kappa_elder.reply.hana": ["Minha avó rezou por esta vila. Volte para a água, ancião.", "My grandmother prayed for this village. Return to the water, elder.", "Mi abuela rezó por esta aldea. Vuelve al agua, anciano.", "Meine Großmutter betete für dieses Dorf. Kehr ins Wasser zurück, Alter.", "Ma grand-mère a prié pour ce village. Retourne à l'eau, ancien.", "Моя бабушка молилась за эту деревню. Вернись в воду, старейшина.", "Nenekku mendoakan desa ini. Kembalilah ke air, Tetua.", "祖母はこの村のために祈った。水へお還りください、長老。", "할머니가 이 마을을 위해 기도했어. 물로 돌아가요, 장로님.", "我祖母曾為這座村子祈禱。回到水裡吧，長老。", "我祖母曾为这座村子祈祷。回到水里吧，长老。"],
    "dialog.kappa_elder.reply.goro": ["Cem anos também pesam em mim, ancião. Descanse.", "A hundred years weigh on me too, elder. Rest.", "Cien años también pesan sobre mí, anciano. Descansa.", "Hundert Jahre lasten auch auf mir, Alter. Ruh dich aus.", "Cent ans pèsent aussi sur moi, ancien. Repose-toi.", "Сто лет давят и на меня, старейшина. Отдохни.", "Seratus tahun juga membebaniku, Tetua. Beristirahatlah.", "百年の重みは拙僧にもある、長老。休まれよ。", "백 년은 나에게도 무겁소, 장로. 쉬시오.", "百年的重量也壓在我身上，長老。安息吧。", "百年的重量也压在我身上，长老。安息吧。"],
    "dialog.kappa_elder.reply.rin": ["Meu irmão foi tocado esta noite. Saia do caminho, kappa.", "My brother was touched tonight. Out of my way, kappa.", "Mi hermano fue tocado esta noche. Apártate, kappa.", "Mein Bruder wurde heute Nacht berührt. Aus dem Weg, Kappa.", "Mon frère a été touché cette nuit. Écarte-toi, kappa.", "Этой ночью коснулись моего брата. С дороги, каппа.", "Kakakku tersentuh malam ini. Minggir, kappa.", "今夜、兄が触れられた。どいて、河童。", "오늘 밤 오빠가 행렬에 닿았어. 비켜, 갓파.", "我哥哥今夜被觸碰了。讓開，河童。", "我哥哥今夜被触碰了。让开，河童。"],
    "dialog.kappa_elder.reply.tora": ["Eu também me lembro dela, velho amigo. Por isso ela não fica com você.", "I remember her too, old friend. That's why she won't stay with you.", "Yo también la recuerdo, viejo amigo. Por eso no se queda contigo.", "Ich erinnere mich auch an sie, alter Freund. Darum bleibt sie nicht bei dir.", "Moi aussi, je me souviens d'elle, vieil ami. C'est pour ça qu'elle ne restera pas avec toi.", "Я тоже помню её, старый друг. Потому она и не останется с тобой.", "Aku juga mengingatnya, kawan lama. Karena itu ia tak akan tinggal bersamamu.", "わしもあの子を覚えておる、古き友よ。だからお前には渡さん。", "나도 그 아이를 기억하네, 옛 친구. 그러니 자네에게 둘 수 없지.", "我也記得她，老朋友。所以她不會留在你身邊。", "我也记得她，老朋友。所以她不会留在你身边。"],
    "dialog.kappa_elder.reply.yuki": ["A luz me queima, a noite me rejeita. E você, de que lado ficou?", "Light burns me, night rejects me. And you, which side did you choose?", "La luz me quema, la noche me rechaza. ¿Y tú, de qué lado quedaste?", "Das Licht verbrennt mich, die Nacht verstößt mich. Und du, auf welcher Seite stehst du?", "La lumière me brûle, la nuit me rejette. Et toi, de quel côté es-tu resté ?", "Свет жжёт меня, ночь отвергает. А ты на чьей стороне?", "Cahaya membakarku, malam menolakku. Dan kau, di pihak mana?", "光は私を焼き、夜は私を拒む。あなたはどちらについたの？", "빛은 나를 태우고 밤은 나를 거부해. 당신은 어느 편에 섰지?", "光灼燒我，夜拒絕我。那你站在哪一邊？", "光灼烧我，夜拒绝我。那你站在哪一边？"],
    "dialog.kappa_elder.aside": ["Curve-se para ele. Kappa sempre devolve a reverência.", "Bow to him. A kappa always returns a bow.", "Inclínate ante él. Un kappa siempre devuelve la reverencia.", "Verneige dich vor ihm. Ein Kappa erwidert immer die Verbeugung.", "Incline-toi devant lui. Un kappa rend toujours le salut.", "Поклонись ему. Каппа всегда отвечает поклоном.", "Membungkuklah padanya. Kappa selalu membalas hormat.", "頭を下げろ。河童は必ずお辞儀を返す。", "그에게 절을 하게. 갓파는 반드시 절을 되돌려 주지.", "向他鞠躬。河童一定會回禮。", "向他鞠躬。河童一定会回礼。"],
    "dialog.kappa_elder.close": ["Hah... a velha cortesia. Mas a água desta noite não derrama fácil.", "Hah... the old courtesy. But tonight's water does not spill easily.", "Ja... la vieja cortesía. Pero el agua de esta noche no se derrama fácil.", "Hah... die alte Höflichkeit. Doch das Wasser dieser Nacht verschüttet sich nicht so leicht.", "Hah... la vieille courtoisie. Mais l'eau de cette nuit ne se renverse pas si facilement.", "Ха... старая учтивость. Но вода этой ночи так просто не прольётся.", "Hah... sopan santun lama. Tapi air malam ini tak mudah tumpah.", "ほう……古い礼儀だな。だが今夜の水は、そう簡単にはこぼれんぞ。", "허... 옛 예법이군. 하지만 오늘 밤의 물은 쉽게 쏟아지지 않는다.", "哈……老派的禮數。但今夜的水可沒那麼容易灑出來。", "哈……老派的礼数。但今夜的水可没那么容易洒出来。"],

    # Kitsune de Nove Caudas (Bambu)
    "dialog.kitsune_nine.open": ["Escute. Esta voz chamava uma filha toda noite, por cem anos.", "Listen. This voice called for a daughter every night, for a hundred years.", "Escucha. Esta voz llamaba a una hija cada noche, durante cien años.", "Hör zu. Diese Stimme rief hundert Jahre lang jede Nacht nach einer Tochter.", "Écoute. Cette voix appelait une fille chaque nuit, pendant cent ans.", "Слушай. Этот голос сто лет каждую ночь звал дочь.", "Dengar. Suara ini memanggil seorang putri setiap malam, selama seratus tahun.", "聞け。この声は百年、毎夜娘を呼んでいた。", "들어라. 이 목소리는 백 년 동안 매일 밤 딸을 불렀다.", "聽著。這聲音百年來夜夜呼喚著一個女兒。", "听着。这声音百年来夜夜呼唤着一个女儿。"],
    "dialog.kitsune_nine.reply.aki": ["Essa voz... por que ela dói no meu peito?", "That voice... why does it ache in my chest?", "Esa voz... ¿por qué me duele en el pecho?", "Diese Stimme... warum schmerzt sie in meiner Brust?", "Cette voix... pourquoi me fait-elle mal à la poitrine ?", "Этот голос... почему от него так больно в груди?", "Suara itu... kenapa dadaku terasa sakit?", "その声……どうして胸が痛むの？", "그 목소리... 왜 가슴이 아픈 거지?", "那聲音……為什麼讓我胸口發疼？", "那声音……为什么让我胸口发疼？"],
    "dialog.kitsune_nine.reply.kenta": ["Uma raposa imitando um pai. Já vi truques mais limpos.", "A fox mimicking a father. I've seen cleaner tricks.", "Una zorra imitando a un padre. He visto trucos más limpios.", "Ein Fuchs, der einen Vater nachahmt. Ich habe sauberere Tricks gesehen.", "Un renard qui imite un père. J'ai vu des tours plus propres.", "Лиса, подражающая отцу. Я видел фокусы и почище.", "Rubah meniru seorang ayah. Aku pernah lihat tipuan yang lebih rapi.", "父親の真似をする狐か。もっとましな手品を見たことがある。", "아비 흉내를 내는 여우라. 더 깔끔한 속임수도 봤지.", "狐狸模仿父親。我見過更乾淨的把戲。", "狐狸模仿父亲。我见过更干净的把戏。"],
    "dialog.kitsune_nine.reply.hana": ["Minha avó também ouviu essa voz. Nunca me contou de quem era.", "My grandmother heard that voice too. She never told me whose it was.", "Mi abuela también oyó esa voz. Nunca me dijo de quién era.", "Auch meine Großmutter hörte diese Stimme. Sie sagte mir nie, wessen sie war.", "Ma grand-mère aussi a entendu cette voix. Elle ne m'a jamais dit à qui elle était.", "Бабушка тоже слышала этот голос. Она так и не сказала мне, чей он.", "Nenekku juga mendengar suara itu. Ia tak pernah bilang milik siapa.", "祖母もその声を聞いていた。誰の声かは、教えてくれなかった。", "할머니도 그 목소리를 들었어. 누구의 목소리인지는 끝내 말해 주지 않았지.", "我祖母也聽過這聲音。她從沒告訴我是誰的。", "我祖母也听过这声音。她从没告诉我是谁的。"],
    "dialog.kitsune_nine.reply.goro": ["Conheci o homem dessa voz. Ele não merece virar truque de raposa.", "I knew the man behind that voice. He doesn't deserve to become a fox's trick.", "Conocí al hombre de esa voz. No merece volverse truco de zorra.", "Ich kannte den Mann hinter dieser Stimme. Er verdient es nicht, zum Fuchstrick zu werden.", "J'ai connu l'homme de cette voix. Il ne mérite pas de devenir un tour de renard.", "Я знал человека с этим голосом. Он не заслужил стать лисьим фокусом.", "Aku mengenal pemilik suara itu. Ia tak pantas jadi tipuan rubah.", "拙僧はその声の主を知っている。狐の手品にされていい男ではない。", "나는 그 목소리의 주인을 알았소. 여우의 속임수가 될 사람이 아니오.", "我認識那聲音的主人。他不該淪為狐狸的把戲。", "我认识那声音的主人。他不该沦为狐狸的把戏。"],
    "dialog.kitsune_nine.reply.rin": ["Não me engane com vozes. Só uma importa: a do meu irmão.", "Don't fool me with voices. Only one matters: my brother's.", "No me engañes con voces. Solo una importa: la de mi hermano.", "Täusch mich nicht mit Stimmen. Nur eine zählt: die meines Bruders.", "Ne me trompe pas avec des voix. Une seule compte : celle de mon frère.", "Не обманывай меня голосами. Важен лишь один: голос брата.", "Jangan tipu aku dengan suara. Hanya satu yang penting: suara kakakku.", "声で惑わさないで。大事なのは兄の声だけ。", "목소리로 날 속이지 마. 중요한 건 하나뿐이야. 오빠의 목소리.", "別拿聲音騙我。只有一個重要：我哥哥的。", "别拿声音骗我。只有一个重要：我哥哥的。"],
    "dialog.kitsune_nine.reply.tora": ["Cale essa voz, raposa. Ela não é sua.", "Silence that voice, fox. It isn't yours.", "Calla esa voz, zorra. No es tuya.", "Schweig mit dieser Stimme, Fuchs. Sie gehört dir nicht.", "Fais taire cette voix, renard. Elle n'est pas à toi.", "Уйми этот голос, лиса. Он не твой.", "Diamkan suara itu, rubah. Itu bukan milikmu.", "その声を黙らせろ、狐。お前のものではない。", "그 목소리를 거두어라, 여우. 네 것이 아니야.", "收起那聲音，狐狸。那不是你的。", "收起那声音，狐狸。那不是你的。"],
    "dialog.kitsune_nine.reply.yuki": ["Meu pai também chamava assim. Do outro lado da luz.", "My father called like that too. From the other side of the light.", "Mi padre también llamaba así. Desde el otro lado de la luz.", "Mein Vater rief auch so. Von der anderen Seite des Lichts.", "Mon père appelait aussi comme ça. De l'autre côté de la lumière.", "Мой отец тоже так звал. С той стороны света.", "Ayahku juga memanggil seperti itu. Dari seberang cahaya.", "私の父もそう呼んでいた。光の向こう側から。", "내 아버지도 그렇게 불렀어. 빛의 저편에서.", "我父親也曾這樣呼喚。在光的另一邊。", "我父亲也曾这样呼唤。在光的另一边。"],
    "dialog.kitsune_nine.aside": ["Não responda à raposa. A voz não é dela.", "Don't answer the fox. The voice isn't hers.", "No le respondas a la zorra. La voz no es suya.", "Antworte der Kitsune nicht. Die Stimme gehört nicht ihr.", "Ne réponds pas au renard. Cette voix n'est pas la sienne.", "Не отвечай лисе. Это не её голос.", "Jangan jawab rubah itu. Suara itu bukan miliknya.", "狐に答えるな。あの声は狐のものではない。", "여우에게 대답하지 마라. 그 목소리는 여우의 것이 아니다.", "別回應那隻狐狸。那聲音不是她的。", "别回应那只狐狸。那声音不是她的。"],
    "dialog.kitsune_nine.close": ["Nove caudas, nove vozes. Qual delas vai te fazer parar?", "Nine tails, nine voices. Which one will make you stop?", "Nueve colas, nueve voces. ¿Cuál de ellas te hará parar?", "Neun Schwänze, neun Stimmen. Welche bringt dich zum Stehen?", "Neuf queues, neuf voix. Laquelle va t'arrêter ?", "Девять хвостов, девять голосов. Какой из них тебя остановит?", "Sembilan ekor, sembilan suara. Yang mana akan menghentikanmu?", "九つの尾に九つの声。どれがお前の足を止める？", "아홉 꼬리, 아홉 목소리. 어느 것이 너를 멈추게 할까?", "九條尾巴，九種聲音。哪一個會讓你停下？", "九条尾巴，九种声音。哪一个会让你停下？"],

    # Monge sem Rosto (Templo)
    "dialog.faceless_monk.open": ["Dei meu rosto para segurar esta porta. Quem veio me render, finalmente?", "I gave my face to hold this gate. Who has come to relieve me, at last?", "Di mi rostro para sostener esta puerta. ¿Quién viene a relevarme, por fin?", "Ich gab mein Gesicht, um dieses Tor zu halten. Wer löst mich endlich ab?", "J'ai donné mon visage pour tenir cette porte. Qui vient enfin me relever ?", "Я отдал лицо, чтобы удержать эти врата. Кто наконец пришёл сменить меня?", "Kuberikan wajahku untuk menahan gerbang ini. Siapa yang akhirnya datang menggantikanku?", "この門を守るため、顔を捧げた。ようやく交代に来たのは誰だ？", "이 문을 지키려 얼굴을 바쳤다. 마침내 나를 대신하러 온 자는 누구냐?", "我獻出臉孔守住這道門。終於來接替我的是誰？", "我献出脸孔守住这道门。终于来接替我的是谁？"],
    "dialog.faceless_monk.reply.aki": ["Eu dormia no selo. Agora vim terminar o seu turno.", "I slept inside the seal. Now I've come to finish your watch.", "Yo dormía en el sello. Ahora vengo a terminar tu turno.", "Ich schlief im Siegel. Jetzt komme ich, um deine Wache zu beenden.", "Je dormais dans le sceau. Je viens finir ta garde.", "Я спала в печати. Теперь я пришла закончить твою стражу.", "Aku tidur di dalam segel. Kini aku datang menuntaskan jagamu.", "私は封印の中で眠っていた。今度は私があなたの番を終わらせる。", "나는 봉인 속에서 잠들어 있었어. 이제 당신의 파수를 끝내러 왔어.", "我曾在封印中沉睡。現在我來結束你的守夜。", "我曾在封印中沉睡。现在我来结束你的守夜。"],
    "dialog.faceless_monk.reply.kenta": ["Não sou da Ordem, monge. Mas hoje a porta é minha.", "I'm not of the Order, monk. But today the gate is mine.", "No soy de la Orden, monje. Pero hoy la puerta es mía.", "Ich gehöre nicht zum Orden, Mönch. Aber heute ist das Tor meins.", "Je ne suis pas de l'Ordre, moine. Mais aujourd'hui, la porte est à moi.", "Я не из Ордена, монах. Но сегодня эти врата мои.", "Aku bukan anggota Ordo, biksu. Tapi hari ini gerbang ini milikku.", "俺は教団の者じゃない、坊さん。だが今日、この門は俺が守る。", "난 결사 사람이 아니야, 스님. 하지만 오늘 이 문은 내가 맡는다.", "我不是教團的人，和尚。但今天這道門歸我。", "我不是教团的人，和尚。但今天这道门归我。"],
    "dialog.faceless_monk.reply.hana": ["Minha avó selou uma menina aqui e escondeu a verdade. Vim ouvir o resto.", "My grandmother sealed a girl here and hid the truth. I've come to hear the rest.", "Mi abuela selló a una niña aquí y ocultó la verdad. Vengo a oír el resto.", "Meine Großmutter versiegelte hier ein Mädchen und verbarg die Wahrheit. Ich will den Rest hören.", "Ma grand-mère a scellé une fillette ici et caché la vérité. Je viens entendre la suite.", "Моя бабушка запечатала здесь девочку и скрыла правду. Я пришла услышать остальное.", "Nenekku menyegel seorang gadis di sini dan menyembunyikan kebenaran. Aku datang mendengar sisanya.", "祖母はここで少女を封じ、真実を隠した。続きを聞きに来ました。", "할머니는 여기서 한 소녀를 봉인하고 진실을 숨겼어. 나머지를 들으러 왔어.", "我祖母在此封印了一個女孩，還隱瞞了真相。我來聽剩下的。", "我祖母在此封印了一个女孩，还隐瞒了真相。我来听剩下的。"],
    "dialog.faceless_monk.reply.goro": ["Mestre... eu fugi naquela noite. Vim pedir perdão de pé.", "Master... I ran that night. I've come to ask forgiveness standing.", "Maestro... huí aquella noche. Vengo a pedir perdón de pie.", "Meister... ich floh in jener Nacht. Ich bitte aufrecht um Vergebung.", "Maître... j'ai fui cette nuit-là. Je viens demander pardon debout.", "Учитель... я бежал в ту ночь. Я пришёл просить прощения стоя.", "Guru... aku kabur malam itu. Aku datang memohon ampun sambil berdiri tegak.", "師よ……あの夜、拙僧は逃げた。立ったまま、許しを乞いに来た。", "스승님... 그날 밤 저는 도망쳤습니다. 이제 서서 용서를 구하러 왔습니다.", "師父……那一夜我逃了。我站著來求您原諒。", "师父……那一夜我逃了。我站着来求您原谅。"],
    "dialog.faceless_monk.reply.rin": ["Não há tempo para culpas. O amanhecer não espera.", "There's no time for guilt. Dawn won't wait.", "No hay tiempo para culpas. El amanecer no espera.", "Keine Zeit für Schuld. Die Dämmerung wartet nicht.", "Pas le temps pour la culpabilité. L'aube n'attend pas.", "Некогда винить себя. Рассвет не ждёт.", "Tak ada waktu untuk rasa bersalah. Fajar tak menunggu.", "罪を語る暇はない。夜明けは待ってくれない。", "죄를 따질 시간 없어. 새벽은 기다려 주지 않아.", "沒時間談罪過。黎明不會等人。", "没时间谈罪过。黎明不会等人。"],
    "dialog.faceless_monk.reply.tora": ["Eu sabia de tudo e me calei. Nós dois falhamos com esta porta.", "I knew everything and kept silent. We both failed this gate.", "Lo sabía todo y me callé. Los dos le fallamos a esta puerta.", "Ich wusste alles und schwieg. Wir beide haben an diesem Tor versagt.", "Je savais tout et je me suis tu. Nous avons tous deux failli devant cette porte.", "Я всё знал и молчал. Мы оба подвели эти врата.", "Aku tahu segalanya dan diam saja. Kita berdua gagal menjaga gerbang ini.", "わしはすべて知っていて黙っていた。この門を裏切ったのは、わしら二人だ。", "나는 다 알면서 입을 다물었네. 우리 둘 다 이 문을 저버렸지.", "我知道一切，卻保持沉默。我們都辜負了這道門。", "我知道一切，却保持沉默。我们都辜负了这道门。"],
    "dialog.faceless_monk.reply.yuki": ["A Ordem me chamaria de inimiga. Ainda assim vim defender a sua porta.", "The Order would call me an enemy. Still, I came to defend your gate.", "La Orden me llamaría enemiga. Aun así vine a defender tu puerta.", "Der Orden würde mich Feindin nennen. Trotzdem kam ich, dein Tor zu verteidigen.", "L'Ordre me traiterait d'ennemie. Pourtant, je viens défendre ta porte.", "Орден назвал бы меня врагом. И всё же я пришла защитить твои врата.", "Ordo akan menyebutku musuh. Meski begitu, aku datang membela gerbangmu.", "教団なら私を敵と呼ぶでしょう。それでも、あなたの門を守りに来た。", "결사라면 나를 적이라 부르겠지. 그래도 당신의 문을 지키러 왔어.", "教團會稱我為敵人。即便如此，我仍來守護你的門。", "教团会称我为敌人。即便如此，我仍来守护你的门。"],
    "dialog.faceless_monk.aside": ["Ele foi o mestre de Goro. Liberte-o, não o destrua.", "He was Goro's master. Free him, don't destroy him.", "Fue el maestro de Goro. Libéralo, no lo destruyas.", "Er war Goros Meister. Befreie ihn, zerstöre ihn nicht.", "C'était le maître de Goro. Libère-le, ne le détruis pas.", "Он был учителем Горо. Освободи его, не уничтожай.", "Ia guru Goro. Bebaskan dia, jangan hancurkan.", "あれは吾郎の師だ。滅ぼすな、解き放て。", "그는 고로의 스승이었네. 부수지 말고 풀어 주게.", "他是吾郎的師父。解放他，別毀了他。", "他是吾郎的师父。解放他，别毁了他。"],
    "dialog.faceless_monk.close": ["Então mostre seu rosto. Eu esqueci o meu.", "Then show me your face. I have forgotten mine.", "Entonces muéstrame tu rostro. Yo olvidé el mío.", "Dann zeig mir dein Gesicht. Ich habe meines vergessen.", "Alors montre-moi ton visage. J'ai oublié le mien.", "Тогда покажи своё лицо. Своё я забыл.", "Kalau begitu, tunjukkan wajahmu. Aku sudah lupa wajahku.", "ならば顔を見せよ。私は自分の顔を忘れた。", "그렇다면 네 얼굴을 보여라. 나는 내 얼굴을 잊었다.", "那就露出你的臉。我已忘了自己的。", "那就露出你的脸。我已忘了自己的。"],

    # Dragão de Cinzas (Dunas): Aki ainda não sabe que Kuroe é o pai.
    "dialog.ash_dragon.open": ["Sou o que restou do fogo dele. Sinto o mesmo calor na sua lanterna.", "I am what remains of his fire. I feel the same heat in your lantern.", "Soy lo que quedó de su fuego. Siento el mismo calor en tu linterna.", "Ich bin, was von seinem Feuer blieb. Ich spüre dieselbe Glut in deiner Laterne.", "Je suis ce qui reste de son feu. Je sens la même chaleur dans ta lanterne.", "Я — то, что осталось от его огня. В твоём фонаре я чую тот же жар.", "Akulah sisa apinya. Kurasakan panas yang sama di lenteramu.", "我はあの方の火の残り。お前の灯籠にも同じ熱を感じる。", "나는 그분의 불이 남긴 것. 네 등불에서 같은 열기가 느껴진다.", "我是他火焰的殘餘。我在你的燈籠裡感到同樣的熱。", "我是他火焰的残余。我在你的灯笼里感到同样的热。"],
    "dialog.ash_dragon.reply.aki": ["O fogo de quem? Por que esta cinza me chama pelo nome?", "Whose fire? Why does this ash call me by name?", "¿El fuego de quién? ¿Por qué esta ceniza me llama por mi nombre?", "Wessen Feuer? Warum ruft mich diese Asche beim Namen?", "Le feu de qui ? Pourquoi cette cendre m'appelle-t-elle par mon nom ?", "Чьего огня? Почему этот пепел зовёт меня по имени?", "Api siapa? Kenapa abu ini memanggil namaku?", "誰の火？どうしてこの灰は私の名を呼ぶの？", "누구의 불? 왜 이 재가 내 이름을 부르지?", "誰的火？為什麼這灰燼叫得出我的名字？", "谁的火？为什么这灰烬叫得出我的名字？"],
    "dialog.ash_dragon.reply.kenta": ["Fogo que não aquece ninguém é só cinza com pressa.", "Fire that warms no one is just ash in a hurry.", "Fuego que no calienta a nadie es solo ceniza con prisa.", "Feuer, das niemanden wärmt, ist nur Asche in Eile.", "Un feu qui ne réchauffe personne n'est que de la cendre pressée.", "Огонь, что никого не греет, — просто пепел, который спешит.", "Api yang tak menghangatkan siapa pun cuma abu yang terburu-buru.", "誰も温めない火なんざ、急いでるだけの灰だ。", "아무도 데우지 못하는 불은 서두르는 재일 뿐이야.", "溫暖不了任何人的火，只是急著成灰。", "温暖不了任何人的火，只是急着成灰。"],
    "dialog.ash_dragon.reply.hana": ["Uma chama apagada que caiu na terra... minha avó escreveu sobre isso.", "A quenched flame that fell to earth... my grandmother wrote about it.", "Una llama apagada que cayó a la tierra... mi abuela escribió sobre eso.", "Eine erloschene Flamme, die zur Erde fiel... meine Großmutter schrieb darüber.", "Une flamme éteinte tombée sur terre... ma grand-mère l'a écrit.", "Погасшее пламя, упавшее на землю... бабушка писала об этом.", "Nyala padam yang jatuh ke bumi... nenekku menulis tentang itu.", "消えて地に落ちた炎……祖母が書き残していた。", "꺼져서 땅에 떨어진 불꽃... 할머니가 그걸 적어 두셨어.", "熄滅後墜落大地的火焰……我祖母寫過這件事。", "熄灭后坠落大地的火焰……我祖母写过这件事。"],
    "dialog.ash_dragon.reply.goro": ["Vi Kuroe apagar a lanterna naquela noite. Você é o que caiu dela.", "I saw Kuroe put out his lantern that night. You are what fell from it.", "Vi a Kuroe apagar la linterna aquella noche. Tú eres lo que cayó de ella.", "Ich sah Kuroe in jener Nacht seine Laterne löschen. Du bist, was aus ihr fiel.", "J'ai vu Kuroe éteindre sa lanterne cette nuit-là. Tu es ce qui en est tombé.", "Я видел, как Куроэ погасил фонарь в ту ночь. Ты — то, что из него выпало.", "Kulihat Kuroe memadamkan lenteranya malam itu. Kaulah yang jatuh darinya.", "あの夜、黒衛が灯籠を消すのを見た。お前はそこからこぼれ落ちたものだ。", "그날 밤 쿠로에가 등불을 끄는 걸 보았소. 그대는 거기서 떨어진 것이오.", "那一夜我看見黑衛熄滅燈籠。你就是從中墜落的東西。", "那一夜我看见黑卫熄灭灯笼。你就是从中坠落的东西。"],
    "dialog.ash_dragon.reply.rin": ["Já cacei bestas de fogo. Nenhuma correu mais que o sol.", "I've hunted fire beasts before. None outran the sun.", "Ya cacé bestias de fuego. Ninguna corrió más que el sol.", "Ich habe schon Feuerbestien gejagt. Keine war schneller als die Sonne.", "J'ai déjà chassé des bêtes de feu. Aucune n'a couru plus vite que le soleil.", "Я уже охотилась на огненных зверей. Ни один не обогнал солнце.", "Aku pernah memburu binatang api. Tak satu pun lebih cepat dari matahari.", "炎の獣なら狩ったことがある。太陽より速く逃げたものはいない。", "불의 짐승은 사냥해 봤어. 해보다 빨리 달아난 놈은 없었지.", "我獵過火獸。沒有一隻跑得過太陽。", "我猎过火兽。没有一只跑得过太阳。"],
    "dialog.ash_dragon.reply.tora": ["Minha família forjou a lanterna de onde você caiu. Volte para ela.", "My family forged the lantern you fell from. Go back to it.", "Mi familia forjó la linterna de la que caíste. Vuelve a ella.", "Meine Familie schmiedete die Laterne, aus der du fielst. Kehr in sie zurück.", "Ma famille a forgé la lanterne d'où tu es tombé. Retournes-y.", "Моя семья выковала фонарь, из которого ты выпал. Вернись в него.", "Keluargaku menempa lentera tempatmu jatuh. Kembalilah ke sana.", "お前がこぼれ落ちた灯籠は、わしの一族が鍛えたものだ。そこへ還れ。", "자네가 떨어져 나온 등불은 우리 집안이 벼린 것이네. 그리로 돌아가게.", "你墜落的那盞燈籠，是我家族鍛造的。回去吧。", "你坠落的那盏灯笼，是我家族锻造的。回去吧。"],
    "dialog.ash_dragon.reply.yuki": ["Também sou metade de algo que se perdeu. Não vou virar cinza.", "I'm also half of something that was lost. I won't turn to ash.", "Yo también soy la mitad de algo que se perdió. No me volveré ceniza.", "Auch ich bin die Hälfte von etwas Verlorenem. Ich werde nicht zu Asche.", "Moi aussi, je suis la moitié de quelque chose de perdu. Je ne deviendrai pas cendre.", "Я тоже половина чего-то утраченного. Я не стану пеплом.", "Aku juga separuh dari sesuatu yang hilang. Aku tak akan jadi abu.", "私も、失われた何かの半分。灰にはならない。", "나도 잃어버린 무언가의 절반이야. 재가 되진 않아.", "我也是某種失落之物的一半。我不會化成灰。", "我也是某种失落之物的一半。我不会化成灰。"],
    "dialog.ash_dragon.aside": ["Cinza é fogo que lembra. Não deixe que ele lembre de você.", "Ash is fire that remembers. Don't let it remember you.", "La ceniza es fuego que recuerda. No dejes que te recuerde.", "Asche ist Feuer, das sich erinnert. Lass nicht zu, dass es sich an dich erinnert.", "La cendre est un feu qui se souvient. Ne le laisse pas se souvenir de toi.", "Пепел — это огонь, который помнит. Не дай ему запомнить тебя.", "Abu adalah api yang mengingat. Jangan biarkan ia mengingatmu.", "灰とは覚えている火だ。あれにお前を覚えさせるな。", "재는 기억하는 불이네. 그것이 자네를 기억하게 두지 말게.", "灰燼是會記憶的火。別讓它記住你。", "灰烬是会记忆的火。别让它记住你。"],
    "dialog.ash_dragon.close": ["Então queime comigo até o amanhecer.", "Then burn with me until dawn.", "Entonces arde conmigo hasta el amanecer.", "Dann brenne mit mir bis zum Morgengrauen.", "Alors brûle avec moi jusqu'à l'aube.", "Тогда гори со мной до рассвета.", "Kalau begitu, terbakarlah bersamaku hingga fajar.", "ならば夜明けまで、我と共に燃えよ。", "그렇다면 새벽까지 나와 함께 타올라라.", "那就與我一同燃燒到黎明。", "那就与我一同燃烧到黎明。"],

    # Kuroe, Senhor da Procissão (Yomi): Aki já sabe que ele é o pai.
    "dialog.kuroe.open": ["Cem anos de procissão... e ainda ouço a voz de quem deixei na luz.", "A hundred years of procession... and I still hear the voice of the one I left in the light.", "Cien años de procesión... y aún oigo la voz de quien dejé en la luz.", "Hundert Jahre Prozession... und noch immer höre ich die Stimme, die ich im Licht zurückließ.", "Cent ans de procession... et j'entends encore la voix de celle que j'ai laissée dans la lumière.", "Сто лет шествия... и я всё ещё слышу голос той, кого оставил в свете.", "Seratus tahun arak-arakan... dan aku masih mendengar suara dia yang kutinggalkan dalam cahaya.", "百年の行列……今も、光の中に残してきた者の声が聞こえる。", "백 년의 행렬... 아직도 빛 속에 두고 온 이의 목소리가 들린다.", "百年的百鬼夜行……我仍聽得見留在光中之人的聲音。", "百年的百鬼夜行……我仍听得见留在光中之人的声音。"],
    "dialog.kuroe.reply.aki": ["Pai. Eu me lembro do brinquedo de madeira. Vim te buscar.", "Father. I remember the wooden toy. I've come to bring you home.", "Padre. Recuerdo el juguete de madera. Vine a buscarte.", "Vater. Ich erinnere mich an das Holzspielzeug. Ich hole dich heim.", "Père. Je me souviens du jouet en bois. Je viens te chercher.", "Отец. Я помню деревянную игрушку. Я пришла за тобой.", "Ayah. Aku ingat mainan kayu itu. Aku datang menjemputmu.", "父さん。木のおもちゃを覚えてる。迎えに来たよ。", "아버지. 나무 장난감을 기억해요. 모시러 왔어요.", "父親。我記得那個木頭玩具。我來接你了。", "父亲。我记得那个木头玩具。我来接你了。"],
    "dialog.kuroe.reply.kenta": ["Minha vila marcha atrás de você. Hoje ela volta para casa.", "My village marches behind you. Today it goes home.", "Mi aldea marcha detrás de ti. Hoy vuelve a casa.", "Mein Dorf marschiert hinter dir. Heute kehrt es heim.", "Mon village marche derrière toi. Aujourd'hui, il rentre chez lui.", "Моя деревня шагает за тобой. Сегодня она вернётся домой.", "Desaku berbaris di belakangmu. Hari ini mereka pulang.", "俺の里がお前の後ろを歩いてる。今日、皆を連れて帰る。", "내 마을이 네 뒤를 따라 행진하고 있어. 오늘 집으로 돌아간다.", "我的村子跟在你身後行進。今天他們要回家。", "我的村子跟在你身后行进。今天他们要回家。"],
    "dialog.kuroe.reply.hana": ["Minha avó selou sua filha para salvá-la. Você não foi traidor.", "My grandmother sealed your daughter to save her. You were no traitor.", "Mi abuela selló a tu hija para salvarla. No fuiste un traidor.", "Meine Großmutter versiegelte deine Tochter, um sie zu retten. Du warst kein Verräter.", "Ma grand-mère a scellé ta fille pour la sauver. Tu n'étais pas un traître.", "Бабушка запечатала твою дочь, чтобы спасти её. Ты не был предателем.", "Nenekku menyegel putrimu untuk menyelamatkannya. Kau bukan pengkhianat.", "祖母はあなたの娘を救うために封じた。あなたは裏切り者じゃない。", "할머니는 당신의 딸을 살리려고 봉인했어요. 당신은 배신자가 아니었어요.", "我祖母封印你的女兒，是為了救她。你不是叛徒。", "我祖母封印你的女儿，是为了救她。你不是叛徒。"],
    "dialog.kuroe.reply.goro": ["Kuroe. A Ordem errou com você. Eu também.", "Kuroe. The Order wronged you. So did I.", "Kuroe. La Orden se equivocó contigo. Yo también.", "Kuroe. Der Orden tat dir Unrecht. Ich auch.", "Kuroe. L'Ordre t'a fait du tort. Moi aussi.", "Куроэ. Орден был несправедлив к тебе. Я тоже.", "Kuroe. Ordo telah salah padamu. Aku juga.", "黒衛。教団はお前に過ちを犯した。拙僧もだ。", "쿠로에. 결사는 그대에게 잘못했소. 나 또한 그렇소.", "黑衛。教團虧欠了你。我也是。", "黑卫。教团亏欠了你。我也是。"],
    "dialog.kuroe.reply.rin": ["Devolva meu irmão, senhor da procissão. Antes do sol.", "Give my brother back, lord of the procession. Before the sun.", "Devuélveme a mi hermano, señor de la procesión. Antes del sol.", "Gib mir meinen Bruder zurück, Herr der Prozession. Vor der Sonne.", "Rends-moi mon frère, seigneur de la procession. Avant le soleil.", "Верни моего брата, владыка шествия. До восхода.", "Kembalikan kakakku, penguasa arak-arakan. Sebelum matahari terbit.", "兄を返して、百鬼の主。日が昇る前に。", "오빠를 돌려줘, 행렬의 주인. 해가 뜨기 전에.", "把我哥哥還來，百鬼之主。在日出之前。", "把我哥哥还来，百鬼之主。在日出之前。"],
    "dialog.kuroe.reply.tora": ["Velho amigo. Guardei sua filha por três gerações. Ela está viva.", "Old friend. I kept your daughter safe for three generations. She is alive.", "Viejo amigo. Guardé a tu hija durante tres generaciones. Está viva.", "Alter Freund. Drei Generationen lang hütete ich deine Tochter. Sie lebt.", "Vieil ami. J'ai gardé ta fille pendant trois générations. Elle est vivante.", "Старый друг. Три поколения я хранил твою дочь. Она жива.", "Kawan lama. Kujaga putrimu selama tiga generasi. Ia masih hidup.", "古き友よ。三代にわたり、お前の娘を守ってきた。あの子は生きている。", "옛 친구여. 삼대에 걸쳐 자네 딸을 지켰네. 그 아이는 살아 있어.", "老朋友。我守護你的女兒三代。她還活著。", "老朋友。我守护你的女儿三代。她还活着。"],
    "dialog.kuroe.reply.yuki": ["Você apagou a luz por amor. Eu nasci de um amor assim.", "You put out the light for love. I was born of a love like that.", "Apagaste la luz por amor. Yo nací de un amor así.", "Du löschtest das Licht aus Liebe. Ich wurde aus solcher Liebe geboren.", "Tu as éteint la lumière par amour. Je suis née d'un amour pareil.", "Ты погасил свет из любви. Я родилась из такой же любви.", "Kau memadamkan cahaya demi cinta. Aku lahir dari cinta seperti itu.", "あなたは愛のために光を消した。私はそういう愛から生まれた。", "당신은 사랑 때문에 빛을 껐지. 나는 그런 사랑에서 태어났어.", "你為愛熄滅了光。我正是從那樣的愛裡誕生的。", "你为爱熄灭了光。我正是从那样的爱里诞生的。"],
    "dialog.kuroe.aside": ["Não ataque o homem. Ataque a noite que o vestiu.", "Don't strike the man. Strike the night that clothed him.", "No ataques al hombre. Ataca a la noche que lo vistió.", "Greif nicht den Mann an. Greif die Nacht an, die ihn kleidet.", "N'attaque pas l'homme. Attaque la nuit qui l'a revêtu.", "Не бей человека. Бей ночь, что его одела.", "Jangan serang orangnya. Seranglah malam yang membungkusnya.", "人を斬るな。あの男をまとった夜を斬れ。", "사람을 치지 말게. 그를 덮어씌운 밤을 치게.", "別攻擊那個人。攻擊披在他身上的黑夜。", "别攻击那个人。攻击披在他身上的黑夜。"],
    "dialog.kuroe.close": ["Então mostre-me o que a luz fez de vocês.", "Then show me what the light has made of you.", "Entonces muéstrenme lo que la luz hizo de ustedes.", "Dann zeigt mir, was das Licht aus euch gemacht hat.", "Alors montrez-moi ce que la lumière a fait de vous.", "Тогда покажите, что сделал из вас свет.", "Kalau begitu, tunjukkan padaku apa yang telah cahaya buat dari kalian.", "ならば見せてみろ。光がお前たちを何に変えたのか。", "그렇다면 보여 다오. 빛이 너희를 무엇으로 만들었는지.", "那就讓我看看，光把你們變成了什麼。", "那就让我看看，光把你们变成了什么。"],

    # Izanami (Encosta dos Mortos)
    "dialog.izanami.open": ["Toda luz desce até mim um dia. Por que a sua sobe a encosta?", "Every light comes down to me one day. Why does yours climb the slope?", "Toda luz desciende hasta mí algún día. ¿Por qué la tuya sube la ladera?", "Jedes Licht sinkt eines Tages zu mir herab. Warum steigt deins den Hang hinauf?", "Toute lumière descend un jour jusqu'à moi. Pourquoi la tienne gravit-elle la pente ?", "Всякий свет однажды нисходит ко мне. Почему твой поднимается по склону?", "Setiap cahaya suatu hari turun kepadaku. Mengapa cahayamu mendaki lereng?", "どんな光も、いつか我がもとへ降りてくる。なぜお前の光は坂を登る？", "모든 빛은 언젠가 내게로 내려온다. 어찌하여 너의 빛은 비탈을 오르느냐?", "所有的光終將降到我身邊。為何你的光卻往坡上爬？", "所有的光终将降到我身边。为何你的光却往坡上爬？"],
    "dialog.izanami.reply.aki": ["Não vim te ferir. Vim fechar a porta com luz.", "I didn't come to hurt you. I came to close the door with light.", "No vine a herirte. Vine a cerrar la puerta con luz.", "Ich kam nicht, um dich zu verletzen. Ich schließe die Tür mit Licht.", "Je ne viens pas te blesser. Je viens fermer la porte avec la lumière.", "Я пришла не ранить тебя. Я пришла закрыть дверь светом.", "Aku tak datang untuk melukaimu. Aku datang menutup pintu dengan cahaya.", "あなたを傷つけに来たんじゃない。光で扉を閉じに来た。", "당신을 해치러 온 게 아니야. 빛으로 문을 닫으러 왔어.", "我不是來傷害你的。我是來用光關上那扇門。", "我不是来伤害你的。我是来用光关上那扇门。"],
    "dialog.izanami.reply.kenta": ["Os tambores eram seus. Hoje eles param.", "The drums were yours. Today they stop.", "Los tambores eran tuyos. Hoy se callan.", "Die Trommeln waren deine. Heute verstummen sie.", "Les tambours, c'était toi. Aujourd'hui, ils se taisent.", "Барабаны были твоими. Сегодня они смолкнут.", "Genderang itu milikmu. Hari ini ia berhenti.", "太鼓はお前のだったか。今日で止める。", "북은 네 것이었군. 오늘 멈춘다.", "那些鼓是你的。今天它們停了。", "那些鼓是你的。今天它们停了。"],
    "dialog.izanami.reply.hana": ["As orações da minha família também eram para você, deusa.", "My family's prayers were for you too, goddess.", "Las oraciones de mi familia también eran para ti, diosa.", "Auch die Gebete meiner Familie galten dir, Göttin.", "Les prières de ma famille t'étaient aussi destinées, déesse.", "Молитвы моей семьи были и для тебя, богиня.", "Doa keluargaku juga untukmu, Dewi.", "私の家の祈りは、あなたにも捧げられていました、女神様。", "우리 집안의 기도는 당신을 위한 것이기도 했어요, 여신이시여.", "我家族的祈禱，也是獻給你的，女神。", "我家族的祈祷，也是献给你的，女神。"],
    "dialog.izanami.reply.goro": ["Prolonguei minha vida por um voto. Hoje eu o cumpro aqui.", "I stretched my life for a vow. Today I fulfill it here.", "Alargué mi vida por un voto. Hoy lo cumplo aquí.", "Ich verlängerte mein Leben für ein Gelübde. Heute erfülle ich es hier.", "J'ai prolongé ma vie pour un vœu. Aujourd'hui, je l'accomplis ici.", "Я продлил жизнь ради обета. Сегодня я исполню его здесь.", "Kuperpanjang hidupku demi sebuah sumpah. Hari ini kutunaikan di sini.", "誓いのために命を延ばしてきた。今日、ここで果たす。", "서원 하나로 목숨을 이어 왔소. 오늘 여기서 그것을 이루겠소.", "我為一個誓願延續生命。今天就在此了結。", "我为一个誓愿延续生命。今天就在此了结。"],
    "dialog.izanami.reply.rin": ["Os vivos ainda me esperam. Não desça mais ninguém.", "The living still wait for me. Take no one else down.", "Los vivos aún me esperan. No bajes a nadie más.", "Die Lebenden warten noch auf mich. Zieh niemanden mehr hinab.", "Les vivants m'attendent encore. N'entraîne plus personne en bas.", "Живые всё ещё ждут меня. Не уводи вниз больше никого.", "Yang hidup masih menungguku. Jangan bawa turun siapa pun lagi.", "生きている人たちが私を待ってる。もう誰も連れて行かないで。", "산 사람들이 아직 나를 기다려. 더는 아무도 끌어내리지 마.", "活著的人還在等我。別再拉任何人下去。", "活着的人还在等我。别再拉任何人下去。"],
    "dialog.izanami.reply.tora": ["Já fui jovem e tive medo de você. Agora só tenho pena.", "I was young once and feared you. Now I only pity you.", "Fui joven y te tuve miedo. Ahora solo siento lástima.", "Ich war einst jung und fürchtete dich. Jetzt habe ich nur Mitleid.", "J'ai été jeune et je t'ai crainte. Maintenant, je n'ai que de la pitié.", "Я был молод и боялся тебя. Теперь мне тебя лишь жаль.", "Dulu aku muda dan takut padamu. Kini aku hanya merasa iba.", "若い頃はお前が怖かった。今は、ただ哀れに思う。", "젊었을 땐 그대가 두려웠네. 이제는 그저 가엾을 뿐이야.", "年輕時我怕你。如今只覺得可憐。", "年轻时我怕你。如今只觉得可怜。"],
    "dialog.izanami.reply.yuki": ["Os vivos me temem e os mortos me rejeitam. Talvez eu te entenda.", "The living fear me and the dead reject me. Maybe I understand you.", "Los vivos me temen y los muertos me rechazan. Quizá te entienda.", "Die Lebenden fürchten mich, die Toten verstoßen mich. Vielleicht verstehe ich dich.", "Les vivants me craignent et les morts me rejettent. Je te comprends peut-être.", "Живые боятся меня, мёртвые отвергают. Может, я тебя понимаю.", "Yang hidup takut padaku dan yang mati menolakku. Mungkin aku memahamimu.", "生者は私を恐れ、死者は私を拒む。あなたの気持ち、わかるかもしれない。", "산 자는 나를 두려워하고 죽은 자는 나를 거부해. 어쩌면 당신을 이해할지도.", "生者懼怕我，死者拒絕我。也許我能懂你。", "生者惧怕我，死者拒绝我。也许我能懂你。"],
    "dialog.izanami.aside": ["Foi nesta encosta que Izanagi fugiu. Não olhe para trás.", "It was on this slope that Izanagi fled. Don't look back.", "Fue en esta ladera donde huyó Izanagi. No mires atrás.", "Auf diesem Hang floh Izanagi. Schau nicht zurück.", "C'est sur cette pente qu'Izanagi a fui. Ne regarde pas en arrière.", "По этому склону бежал Идзанаги. Не оглядывайся.", "Di lereng inilah Izanagi kabur. Jangan menoleh ke belakang.", "伊邪那岐が逃げたのはこの坂だ。振り返るな。", "이자나기가 도망친 곳이 바로 이 비탈이네. 뒤돌아보지 말게.", "伊邪那岐就是從這道坡逃走的。別回頭。", "伊邪那岐就是从这道坡逃走的。别回头。"],
    "dialog.izanami.close": ["Os vivos me abandonaram. Mostre-me que você não vai.", "The living abandoned me. Show me that you won't.", "Los vivos me abandonaron. Muéstrame que tú no lo harás.", "Die Lebenden verließen mich. Zeig mir, dass du es nicht tust.", "Les vivants m'ont abandonnée. Montre-moi que tu ne le feras pas.", "Живые покинули меня. Покажи, что ты не покинешь.", "Yang hidup meninggalkanku. Tunjukkan bahwa kau tidak akan.", "生者は我を捨てた。お前は捨てぬと示してみよ。", "산 자는 나를 버렸다. 너는 그러지 않으리라 보여 다오.", "生者拋棄了我。讓我看看你不會。", "生者抛弃了我。让我看看你不会。"],

    # Guardiões do Limiar (7:30). Onikuma (Vila)
    "dialog.onikuma.open": ["Cem invernos guardei esta trilha. Para onde pensa que vai?", "A hundred winters I've guarded this trail. Where do you think you're going?", "Cien inviernos guardé este sendero. ¿Adónde crees que vas?", "Hundert Winter bewachte ich diesen Pfad. Wohin glaubst du zu gehen?", "J'ai gardé ce sentier cent hivers. Où crois-tu aller ?", "Сто зим я стерёг эту тропу. И куда же ты идёшь?", "Seratus musim dingin kujaga jalan ini. Mau ke mana kau?", "百の冬、この道を守ってきた。どこへ行くつもりだ？", "백 번의 겨울 동안 이 길을 지켰다. 어디로 가려는 거냐?", "我守這條小徑一百個寒冬。你以為要去哪？", "我守这条小径一百个寒冬。你以为要去哪？"],
    "dialog.onikuma.reply.aki": ["Para onde a noite esconde o resto desta vila.", "To where the night hides the rest of this village.", "Adonde la noche esconde el resto de esta aldea.", "Dorthin, wo die Nacht den Rest dieses Dorfes versteckt.", "Là où la nuit cache le reste de ce village.", "Туда, где ночь прячет остальную деревню.", "Ke tempat malam menyembunyikan sisa desa ini.", "夜がこの村の残りを隠している場所へ。", "밤이 이 마을의 나머지를 숨긴 곳으로.", "去黑夜藏起這村子其餘部分的地方。", "去黑夜藏起这村子其余部分的地方。"],
    "dialog.onikuma.reply.kenta": ["Sombras não pedem licença, urso.", "Shadows don't ask permission, bear.", "Las sombras no piden permiso, oso.", "Schatten fragen nicht um Erlaubnis, Bär.", "Les ombres ne demandent pas la permission, ours.", "Тени не спрашивают разрешения, медведь.", "Bayangan tak minta izin, beruang.", "影は断りなど入れない、熊。", "그림자는 허락을 구하지 않아, 곰.", "影子不需要許可，熊。", "影子不需要许可，熊。"],
    "dialog.onikuma.reply.hana": ["Peço licença aos kami da mata. A você, não.", "I ask leave of the forest's kami. Not of you.", "Pido permiso a los kami del bosque. A ti, no.", "Ich bitte die Kami des Waldes um Erlaubnis. Dich nicht.", "Je demande la permission aux kami de la forêt. Pas à toi.", "Я прошу дозволения у ками леса. Не у тебя.", "Aku minta izin pada kami hutan. Bukan padamu.", "森の神々にはお許しを請います。あなたには請わない。", "숲의 가미께는 허락을 구해. 너한테는 아니야.", "我向林中的神明請求許可。不是向你。", "我向林中的神明请求许可。不是向你。"],
    "dialog.onikuma.reply.goro": ["Também vivi invernos demais. Deixe-me passar em paz.", "I too have lived too many winters. Let me pass in peace.", "Yo también viví demasiados inviernos. Déjame pasar en paz.", "Auch ich lebte zu viele Winter. Lass mich in Frieden vorbei.", "Moi aussi, j'ai vécu trop d'hivers. Laisse-moi passer en paix.", "Я тоже прожил слишком много зим. Пропусти меня с миром.", "Aku juga hidup terlalu banyak musim dingin. Biarkan aku lewat dengan damai.", "拙僧も冬を越えすぎた。穏やかに通してくれ。", "나 또한 너무 많은 겨울을 살았소. 조용히 지나가게 해 주시오.", "我也活過太多寒冬了。讓我平靜地過去吧。", "我也活过太多寒冬了。让我平静地过去吧。"],
    "dialog.onikuma.reply.rin": ["Já cacei ursos maiores. Nenhum andava em duas patas.", "I've hunted bigger bears. None walked on two legs.", "Ya cacé osos más grandes. Ninguno andaba en dos patas.", "Ich habe größere Bären gejagt. Keiner ging auf zwei Beinen.", "J'ai chassé des ours plus gros. Aucun ne marchait sur deux pattes.", "Я охотилась на медведей и покрупнее. Ни один не ходил на двух лапах.", "Aku pernah memburu beruang yang lebih besar. Tak satu pun berjalan dengan dua kaki.", "もっと大きな熊も狩った。二本足で歩くのはいなかったけど。", "더 큰 곰도 사냥해 봤어. 두 발로 걷는 놈은 없었지만.", "我獵過更大的熊。沒有一隻用兩條腿走路。", "我猎过更大的熊。没有一只用两条腿走路。"],
    "dialog.onikuma.reply.tora": ["Eu forjava armadilhas de urso, sabia? Saia da trilha.", "I used to forge bear traps, you know. Off the trail.", "Yo forjaba trampas para osos, ¿sabías? Sal del sendero.", "Ich schmiedete einst Bärenfallen, weißt du? Runter vom Pfad.", "Je forgeais des pièges à ours, tu sais ? Quitte le sentier.", "Я ковал медвежьи капканы, знаешь ли. Прочь с тропы.", "Dulu aku menempa jebakan beruang, tahu? Minggir dari jalan.", "わしは熊の罠を鍛えておったんだぞ。道を空けろ。", "내가 곰 덫을 벼리던 사람이란 걸 아나? 길에서 비키게.", "我以前打造過捕熊陷阱，知道嗎？讓開小徑。", "我以前打造过捕熊陷阱，知道吗？让开小径。"],
    "dialog.onikuma.reply.yuki": ["Você deixou de ser bicho e não virou gente. Somos parecidos.", "You stopped being a beast but never became human. We're alike.", "Dejaste de ser bestia y no te volviste humano. Nos parecemos.", "Du bist kein Tier mehr und doch kein Mensch. Wir sind uns ähnlich.", "Tu n'es plus une bête, sans être devenu humain. Nous nous ressemblons.", "Ты перестал быть зверем, но не стал человеком. Мы похожи.", "Kau berhenti jadi binatang tapi tak menjadi manusia. Kita mirip.", "獣でもなく、人にもなれなかった。私たち、似ているね。", "짐승도 아니고 사람도 되지 못했지. 우린 닮았어.", "你不再是野獸，卻也沒成為人。我們很像。", "你不再是野兽，却也没成为人。我们很像。"],
    "dialog.onikuma.aside": ["Atrás dele há um portão para o outro mundo.", "Behind him lies a gate to the other world.", "Tras él hay un portal al otro mundo.", "Hinter ihm liegt ein Tor in die andere Welt.", "Derrière lui se trouve une porte vers l'autre monde.", "За ним врата в иной мир.", "Di belakangnya ada gerbang ke dunia lain.", "あいつの後ろに、異界への門がある。", "저 녀석 뒤에 저세상으로 가는 문이 있네.", "牠身後有一道通往異界的門。", "它身后有一道通往异界的门。"],
    "dialog.onikuma.close": ["Então passe por cima de mim.", "Then go through me.", "Entonces pasa por encima de mí.", "Dann musst du an mir vorbei.", "Alors passe sur mon corps.", "Тогда пройди через меня.", "Kalau begitu, lewati aku dulu.", "ならば、俺を越えていけ。", "그렇다면 나를 넘어서 가라.", "那就從我身上踏過去。", "那就从我身上踏过去。"],

    # Nuppeppō (Bambu)
    "dialog.nuppeppo.open": ["Glub... tantos rostos passaram pelo bambu. Nenhum ficou comigo.", "Glub... so many faces passed through the bamboo. None stayed with me.", "Glub... tantos rostros pasaron por el bambú. Ninguno se quedó conmigo.", "Glub ... so viele Gesichter zogen durch den Bambus. Keins blieb bei mir.", "Glub... tant de visages ont traversé le bambou. Aucun n'est resté avec moi.", "Бульк... столько лиц прошло через бамбук. Ни одно не осталось со мной.", "Glub... begitu banyak wajah melewati bambu. Tak satu pun tinggal bersamaku.", "ぐぶ……竹林をたくさんの顔が通った。ひとつも残ってくれなかった。", "꾸륵... 수많은 얼굴이 대숲을 지나갔다. 하나도 내 곁에 남지 않았다.", "咕嚕……好多臉孔穿過竹林。沒有一張留給我。", "咕噜……好多脸孔穿过竹林。没有一张留给我。"],
    "dialog.nuppeppo.reply.aki": ["Eu também perdi quem eu era. Mas não vou tomar o de ninguém.", "I lost who I was too. But I won't take anyone else's.", "Yo también perdí quién era. Pero no tomaré el de nadie.", "Auch ich verlor, wer ich war. Aber ich nehme niemandem seins.", "Moi aussi, j'ai perdu qui j'étais. Mais je ne prendrai celui de personne.", "Я тоже потеряла себя. Но чужого не возьму.", "Aku juga kehilangan diriku. Tapi aku tak akan mengambil milik orang lain.", "私も自分を失った。でも、誰かのものを奪ったりしない。", "나도 내가 누구였는지 잃었어. 하지만 남의 것을 빼앗진 않아.", "我也失去了曾經的自己。但我不會奪走別人的。", "我也失去了曾经的自己。但我不会夺走别人的。"],
    "dialog.nuppeppo.reply.kenta": ["Meu rosto fica coberto. Por bons motivos.", "My face stays covered. For good reasons.", "Mi rostro queda cubierto. Por buenas razones.", "Mein Gesicht bleibt bedeckt. Aus gutem Grund.", "Mon visage reste couvert. Pour de bonnes raisons.", "Моё лицо остаётся скрытым. Не без причины.", "Wajahku tetap tertutup. Ada alasannya.", "俺の顔は覆ったままだ。理由があってな。", "내 얼굴은 가려 둔다. 그럴 만한 이유가 있지.", "我的臉一直遮著。自有道理。", "我的脸一直遮着。自有道理。"],
    "dialog.nuppeppo.reply.hana": ["Que os mortos esquecidos encontrem descanso, não rostos.", "May the forgotten dead find rest, not faces.", "Que los muertos olvidados hallen descanso, no rostros.", "Mögen die vergessenen Toten Ruhe finden, keine Gesichter.", "Que les morts oubliés trouvent le repos, pas des visages.", "Пусть забытые мёртвые обретут покой, а не лица.", "Semoga arwah yang terlupa menemukan istirahat, bukan wajah.", "忘れられた死者に、顔ではなく安らぎを。", "잊힌 망자들이 얼굴이 아니라 안식을 얻기를.", "願被遺忘的亡者得到安息，而非臉孔。", "愿被遗忘的亡者得到安息，而非脸孔。"],
    "dialog.nuppeppo.reply.goro": ["Meu mestre deu o rosto por uma porta. O meu é da penitência.", "My master gave his face for a gate. Mine belongs to penance.", "Mi maestro dio su rostro por una puerta. El mío es de la penitencia.", "Mein Meister gab sein Gesicht für ein Tor. Meins gehört der Buße.", "Mon maître a donné son visage pour une porte. Le mien appartient à la pénitence.", "Мой учитель отдал лицо за врата. Моё принадлежит покаянию.", "Guruku memberikan wajahnya demi gerbang. Wajahku milik penebusan.", "我が師は門のために顔を捧げた。拙僧の顔は贖罪のものだ。", "내 스승은 문을 위해 얼굴을 바쳤소. 내 얼굴은 참회의 것이오.", "我師父為一道門獻出了臉。我的臉屬於懺悔。", "我师父为一道门献出了脸。我的脸属于忏悔。"],
    "dialog.nuppeppo.reply.rin": ["Não tenho tempo de te caçar inteiro, coisa.", "I don't have time to hunt all of you, thing.", "No tengo tiempo de cazarte entero, cosa.", "Ich hab keine Zeit, dich ganz zu jagen, Ding.", "Je n'ai pas le temps de te chasser en entier, chose.", "Мне некогда охотиться на тебя целиком, тварь.", "Aku tak punya waktu memburumu sampai habis, makhluk.", "あんたを丸ごと狩ってる暇はないの、化け物。", "너를 통째로 사냥할 시간은 없어, 괴물아.", "我沒空把你整隻獵完，怪東西。", "我没空把你整只猎完，怪东西。"],
    "dialog.nuppeppo.reply.tora": ["Este rosto viu setenta anos de forja. Não é para você.", "This face has seen seventy years at the forge. It's not for you.", "Este rostro vio setenta años de forja. No es para ti.", "Dieses Gesicht sah siebzig Jahre Schmiede. Es ist nicht für dich.", "Ce visage a vu soixante-dix ans de forge. Il n'est pas pour toi.", "Это лицо видело семьдесят лет кузницы. Оно не для тебя.", "Wajah ini telah melihat tujuh puluh tahun di tempaan. Bukan untukmu.", "この顔は七十年、炉を見てきた。お前にはやらん。", "이 얼굴은 칠십 년 대장간을 지켜봤네. 자네 몫이 아니야.", "這張臉看過七十年的爐火。不是給你的。", "这张脸看过七十年的炉火。不是给你的。"],
    "dialog.nuppeppo.reply.yuki": ["Metade do meu rosto é oni. Ainda quer?", "Half my face is oni. Still want it?", "La mitad de mi rostro es oni. ¿Aún lo quieres?", "Mein halbes Gesicht ist Oni. Willst du es noch?", "La moitié de mon visage est oni. Tu le veux toujours ?", "Половина моего лица — они. Всё ещё хочешь?", "Separuh wajahku oni. Masih mau?", "私の顔の半分は鬼。それでも欲しい？", "내 얼굴의 절반은 오니야. 그래도 갖고 싶어?", "我的臉有一半是鬼。還想要嗎？", "我的脸有一半是鬼。还想要吗？"],
    "dialog.nuppeppo.aside": ["Cada pedaço que cai vira outro faminto. Não deixe que se espalhe.", "Every piece that falls becomes another hungry one. Don't let it spread.", "Cada trozo que cae se vuelve otro hambriento. No dejes que se esparza.", "Jedes Stück, das abfällt, wird ein neuer Hungriger. Lass es sich nicht ausbreiten.", "Chaque morceau qui tombe devient un autre affamé. Ne le laisse pas se répandre.", "Каждый упавший кусок становится новым голодным. Не дай ему расползтись.", "Setiap potongan yang jatuh jadi makhluk lapar baru. Jangan biarkan menyebar.", "落ちた欠片はどれも飢えた化け物になる。広がらせるな。", "떨어지는 조각마다 굶주린 놈이 되네. 퍼지게 두지 말게.", "每塊掉落的肉都會變成另一個餓鬼。別讓它蔓延。", "每块掉落的肉都会变成另一个饿鬼。别让它蔓延。"],
    "dialog.nuppeppo.close": ["Glub... então vou pegar pedaço por pedaço.", "Glub... then I'll take you piece by piece.", "Glub... entonces te tomaré pedazo a pedazo.", "Glub ... dann hole ich dich Stück für Stück.", "Glub... alors je te prendrai morceau par morceau.", "Бульк... тогда заберу тебя по кусочку.", "Glub... kalau begitu, akan kuambil sepotong demi sepotong.", "ぐぶ……なら、ひとかけらずつもらう。", "꾸륵... 그럼 한 조각씩 가져가겠다.", "咕嚕……那我就一塊一塊地拿。", "咕噜……那我就一块一块地拿。"],

    # Onmoraki (Templo): aparte da Hana.
    "dialog.onmoraki.open": ["Respiro o hálito dos mortos sem prece. Este templo está cheio deles.", "I breathe the breath of the unprayed dead. This temple is full of them.", "Respiro el aliento de los muertos sin oración. Este templo está lleno de ellos.", "Ich atme den Hauch der Toten ohne Gebet. Dieser Tempel ist voll von ihnen.", "Je respire le souffle des morts sans prière. Ce temple en est plein.", "Я дышу дыханием мёртвых без молитвы. Этот храм полон ими.", "Aku menghirup napas arwah tanpa doa. Kuil ini penuh dengan mereka.", "弔われぬ死者の息を吸う。この寺は彼らで満ちている。", "기도받지 못한 망자의 숨을 들이쉰다. 이 사원은 그들로 가득하다.", "我吸入無人超度的亡者之息。這座寺裡滿是他們。", "我吸入无人超度的亡者之息。这座寺里满是他们。"],
    "dialog.onmoraki.reply.aki": ["Então eu acendo a luz que eles não tiveram.", "Then I'll light the lamp they never had.", "Entonces encenderé la luz que ellos no tuvieron.", "Dann entzünde ich das Licht, das sie nie hatten.", "Alors j'allume la lumière qu'ils n'ont pas eue.", "Тогда я зажгу свет, которого у них не было.", "Kalau begitu, akan kunyalakan cahaya yang tak pernah mereka miliki.", "なら、彼らが持てなかった灯を私がともす。", "그럼 그들이 갖지 못한 빛을 내가 밝힐게.", "那我就點亮他們不曾擁有的光。", "那我就点亮他们不曾拥有的光。"],
    "dialog.onmoraki.reply.kenta": ["Ninja não ganha prece. Aprendemos a não precisar.", "Ninja get no prayers. We learn not to need them.", "Los ninja no reciben oraciones. Aprendemos a no necesitarlas.", "Ninja bekommen keine Gebete. Wir lernen, keine zu brauchen.", "Les ninjas n'ont pas de prières. On apprend à s'en passer.", "За ниндзя не молятся. Мы учимся обходиться без этого.", "Ninja tak didoakan. Kami belajar tak membutuhkannya.", "忍に弔いはない。なくても平気になるよう育つ。", "닌자는 기도를 받지 못해. 필요 없도록 배우지.", "忍者沒人超度。我們學會不需要。", "忍者没人超度。我们学会不需要。"],
    "dialog.onmoraki.reply.hana": ["Eu rezo por eles agora. Você pode descansar.", "I pray for them now. You can rest.", "Yo rezo por ellos ahora. Puedes descansar.", "Ich bete jetzt für sie. Du darfst ruhen.", "Je prie pour eux maintenant. Tu peux te reposer.", "Теперь я молюсь за них. Ты можешь отдохнуть.", "Aku mendoakan mereka sekarang. Kau boleh beristirahat.", "今、私が彼らのために祈ります。あなたも休んで。", "이제 내가 그들을 위해 기도할게. 너는 쉬어도 돼.", "現在由我為他們祈禱。你可以安息了。", "现在由我为他们祈祷。你可以安息了。"],
    "dialog.onmoraki.reply.goro": ["Eram meus irmãos de templo. Eu devia ter rezado por eles.", "They were my temple brothers. I should have prayed for them.", "Eran mis hermanos del templo. Debí haber rezado por ellos.", "Sie waren meine Tempelbrüder. Ich hätte für sie beten sollen.", "C'étaient mes frères du temple. J'aurais dû prier pour eux.", "Это были мои братья по храму. Мне следовало молиться за них.", "Mereka saudara seperguruanku di kuil. Seharusnya aku mendoakan mereka.", "彼らは寺の兄弟だった。拙僧が弔うべきだった。", "그들은 내 사원 형제들이었소. 내가 그들을 위해 기도했어야 했소.", "他們是我同寺的師兄弟。我早該為他們誦經。", "他们是我同寺的师兄弟。我早该为他们诵经。"],
    "dialog.onmoraki.reply.rin": ["Reze depois. Hoje preciso de cada minuto.", "Pray later. Today I need every minute.", "Reza después. Hoy necesito cada minuto.", "Bete später. Heute brauche ich jede Minute.", "Prie plus tard. Aujourd'hui, j'ai besoin de chaque minute.", "Помолишься потом. Сегодня мне дорога каждая минута.", "Berdoalah nanti. Hari ini aku butuh setiap menit.", "祈るのは後で。今日は一分も無駄にできない。", "기도는 나중에. 오늘은 일 분도 아까워.", "晚點再祈禱。今天我需要每一分鐘。", "晚点再祈祷。今天我需要每一分钟。"],
    "dialog.onmoraki.reply.tora": ["Forjei os sinos que deviam tocar por eles. Calaram cedo demais.", "I forged the bells that should have rung for them. They fell silent too soon.", "Forjé las campanas que debían sonar por ellos. Callaron demasiado pronto.", "Ich schmiedete die Glocken, die für sie läuten sollten. Sie verstummten zu früh.", "J'ai forgé les cloches qui devaient sonner pour eux. Elles se sont tues trop tôt.", "Я выковал колокола, что должны были звонить по ним. Они смолкли слишком рано.", "Kutempa lonceng yang seharusnya berbunyi untuk mereka. Terlalu cepat terdiam.", "彼らのために鳴るはずの鐘を、わしが鍛えた。早く黙りすぎた。", "그들을 위해 울려야 할 종을 내가 벼렸네. 너무 일찍 멎었지.", "我鍛造了本該為他們而鳴的鐘。它們太早沉默了。", "我锻造了本该为他们而鸣的钟。它们太早沉默了。"],
    "dialog.onmoraki.reply.yuki": ["Ninguém reza por meia-oni também. Mas sigo de pé.", "No one prays for a half-oni either. But I'm still standing.", "Nadie reza por una medio oni tampoco. Pero sigo en pie.", "Für eine Halb-Oni betet auch niemand. Doch ich stehe noch.", "Personne ne prie pour une demi-oni non plus. Mais je tiens debout.", "За полу-они тоже никто не молится. Но я всё ещё стою.", "Tak ada yang mendoakan setengah oni juga. Tapi aku masih berdiri.", "半分鬼の私のためにも、誰も祈らない。それでも立っている。", "반쪽 오니를 위해 기도하는 사람도 없어. 그래도 나는 서 있어.", "也沒人為半鬼祈禱。但我依然站著。", "也没人为半鬼祈祷。但我依然站着。"],
    "dialog.onmoraki.aside": ["As penas dele são fogo frio. Não deixe que toquem a lanterna.", "Its feathers are cold fire. Don't let them touch the lantern.", "Sus plumas son fuego frío. No dejes que toquen la linterna.", "Seine Federn sind kaltes Feuer. Lass sie die Laterne nicht berühren.", "Ses plumes sont un feu froid. Ne les laisse pas toucher la lanterne.", "Его перья — холодный огонь. Не дай им коснуться фонаря.", "Bulunya adalah api dingin. Jangan biarkan menyentuh lentera.", "あの羽は冷たい炎。灯籠に触れさせないで。", "저 깃털은 차가운 불이야. 등불에 닿게 하지 마.", "牠的羽毛是冷火。別讓它們碰到燈籠。", "它的羽毛是冷火。别让它们碰到灯笼。"],
    "dialog.onmoraki.close": ["Então queime minhas penas e veja quem chora por elas.", "Then burn my feathers and see who weeps for them.", "Entonces quema mis plumas y mira quién llora por ellas.", "Dann verbrenne meine Federn und sieh, wer um sie weint.", "Alors brûle mes plumes et vois qui les pleure.", "Тогда сожги мои перья и посмотри, кто по ним заплачет.", "Kalau begitu, bakar buluku dan lihat siapa yang menangisinya.", "ならば我が羽を焼き、誰が泣くか見るがいい。", "그렇다면 내 깃털을 태우고 누가 우는지 보아라.", "那就燒了我的羽毛，看看誰會為它們哭泣。", "那就烧了我的羽毛，看看谁会为它们哭泣。"],

    # Onibi (Dunas): aparte da Rin.
    "dialog.onibi.open": ["Fui a última fogueira desta estrada. Ninguém voltou para me alimentar.", "I was the last fire on this road. No one came back to feed me.", "Fui la última hoguera de este camino. Nadie volvió para alimentarme.", "Ich war das letzte Feuer an dieser Straße. Niemand kam zurück, um mich zu nähren.", "J'étais le dernier feu de cette route. Personne n'est revenu me nourrir.", "Я был последним костром на этой дороге. Никто не вернулся меня покормить.", "Akulah api unggun terakhir di jalan ini. Tak ada yang kembali memberiku makan.", "俺はこの道の最後の焚き火だった。誰も薪をくべに戻らなかった。", "나는 이 길의 마지막 모닥불이었다. 아무도 나를 먹이러 돌아오지 않았다.", "我是這條路上最後一堆篝火。沒有人回來餵養我。", "我是这条路上最后一堆篝火。没有人回来喂养我。"],
    "dialog.onibi.reply.aki": ["Minha lanterna também é fogo. Mas ela não come almas.", "My lantern is fire too. But it doesn't eat souls.", "Mi linterna también es fuego. Pero no come almas.", "Meine Laterne ist auch Feuer. Aber sie frisst keine Seelen.", "Ma lanterne aussi est du feu. Mais elle ne dévore pas les âmes.", "Мой фонарь тоже огонь. Но он не ест души.", "Lenteraku juga api. Tapi ia tak memakan jiwa.", "私の灯籠も火。でも魂は食べない。", "내 등불도 불이야. 하지만 영혼을 먹지는 않아.", "我的燈籠也是火。但它不吞噬靈魂。", "我的灯笼也是火。但它不吞噬灵魂。"],
    "dialog.onibi.reply.kenta": ["Fogo que anda sozinho sempre procura a lenha errada.", "Fire that wanders alone always looks for the wrong kindling.", "Fuego que anda solo siempre busca la leña equivocada.", "Feuer, das allein wandert, sucht immer das falsche Holz.", "Un feu qui erre seul cherche toujours le mauvais bois.", "Огонь, что бродит один, всегда ищет не те дрова.", "Api yang berkelana sendirian selalu mencari kayu bakar yang salah.", "独りで歩く火は、いつも間違った薪を探す。", "혼자 떠도는 불은 늘 엉뚱한 장작을 찾지.", "獨自遊蕩的火，總會找錯柴。", "独自游荡的火，总会找错柴。"],
    "dialog.onibi.reply.hana": ["Fogo sagrado nasce de oferenda, não de fome.", "Sacred fire is born of offering, not hunger.", "El fuego sagrado nace de la ofrenda, no del hambre.", "Heiliges Feuer entsteht aus Opfergabe, nicht aus Hunger.", "Le feu sacré naît de l'offrande, pas de la faim.", "Священный огонь рождается из подношения, а не из голода.", "Api suci lahir dari persembahan, bukan dari lapar.", "聖なる火は供物から生まれる。飢えからではない。", "신성한 불은 굶주림이 아니라 공양에서 태어나.", "聖火源於供奉，而非飢餓。", "圣火源于供奉，而非饥饿。"],
    "dialog.onibi.reply.goro": ["Já me sentei ao seu lado numa noite fria. Lembro do calor.", "I once sat beside you on a cold night. I remember the warmth.", "Una noche fría me senté a tu lado. Recuerdo el calor.", "In einer kalten Nacht saß ich einst bei dir. Ich erinnere mich an die Wärme.", "Je me suis déjà assis près de toi par une nuit froide. Je me souviens de la chaleur.", "Однажды холодной ночью я сидел рядом с тобой. Я помню то тепло.", "Aku pernah duduk di sisimu pada malam yang dingin. Aku ingat hangatnya.", "寒い夜、お前のそばに座ったことがある。あの温もりを覚えている。", "추운 밤 그대 곁에 앉은 적이 있소. 그 온기를 기억하오.", "我曾在寒夜坐在你身旁。我記得那份溫暖。", "我曾在寒夜坐在你身旁。我记得那份温暖。"],
    "dialog.onibi.reply.rin": ["Fogueira errante não assusta caçadora. Já dormi perto de piores.", "A wandering fire doesn't scare a hunter. I've slept near worse.", "Una hoguera errante no asusta a una cazadora. He dormido cerca de peores.", "Ein wanderndes Feuer schreckt keine Jägerin. Ich schlief schon neben Schlimmerem.", "Un feu errant n'effraie pas une chasseuse. J'ai dormi près de pire.", "Блуждающий костёр охотницу не напугает. Я спала у костров и похуже.", "Api unggun pengembara tak menakuti pemburu. Aku pernah tidur dekat yang lebih buruk.", "さまよう焚き火なんか狩人は怖くない。もっとひどいのの隣で寝たこともある。", "떠도는 모닥불 따위에 사냥꾼은 겁먹지 않아. 더 험한 것 옆에서도 자 봤어.", "遊蕩的篝火嚇不倒獵人。我在更糟的東西旁睡過。", "游荡的篝火吓不倒猎人。我在更糟的东西旁睡过。"],
    "dialog.onibi.reply.tora": ["Conheço fogo melhor que ninguém. Você está faminto, não forte.", "I know fire better than anyone. You're hungry, not strong.", "Conozco el fuego mejor que nadie. Estás hambriento, no fuerte.", "Ich kenne Feuer wie kein anderer. Du bist hungrig, nicht stark.", "Je connais le feu mieux que personne. Tu es affamé, pas fort.", "Я знаю огонь лучше всех. Ты голоден, а не силён.", "Aku lebih kenal api daripada siapa pun. Kau lapar, bukan kuat.", "火のことなら誰より知っておる。お前は強いのではない、飢えているだけだ。", "불이라면 내가 누구보다 잘 알지. 자네는 강한 게 아니라 굶주린 거야.", "我比誰都懂火。你是餓了，不是強。", "我比谁都懂火。你是饿了，不是强。"],
    "dialog.onibi.reply.yuki": ["A luz me queima. Vai ter que se esforçar mais.", "Light already burns me. You'll have to try harder.", "La luz ya me quema. Tendrás que esforzarte más.", "Licht verbrennt mich ohnehin. Du musst dich mehr anstrengen.", "La lumière me brûle déjà. Il va falloir faire mieux.", "Меня и так жжёт свет. Придётся постараться сильнее.", "Cahaya sudah membakarku. Kau harus berusaha lebih keras.", "光ならもう私を焼いている。もっと頑張らないとね。", "빛은 이미 나를 태우고 있어. 더 애써야 할 거야.", "光早就在灼燒我了。你得再努力些。", "光早就在灼烧我了。你得再努力些。"],
    "dialog.onibi.aside": ["Ele vive do que arde. Não deixe que se alimente de você.", "It lives on what burns. Don't let it feed on you.", "Vive de lo que arde. No dejes que se alimente de ti.", "Es lebt von allem, was brennt. Lass es sich nicht von dir nähren.", "Il vit de ce qui brûle. Ne le laisse pas se nourrir de toi.", "Он живёт тем, что горит. Не дай ему кормиться тобой.", "Ia hidup dari apa yang terbakar. Jangan biarkan ia memangsamu.", "あいつは燃えるものを糧にする。あなたを食わせないで。", "저건 타는 걸 먹고 살아. 너를 먹이로 삼게 두지 마.", "它靠燃燒的東西維生。別讓它拿你當柴。", "它靠燃烧的东西维生。别让它拿你当柴。"],
    "dialog.onibi.close": ["Venha. Toda fogueira precisa de lenha nova.", "Come. Every fire needs new kindling.", "Ven. Toda hoguera necesita leña nueva.", "Komm. Jedes Feuer braucht neues Holz.", "Viens. Tout feu a besoin de bois neuf.", "Иди сюда. Каждому костру нужны новые дрова.", "Kemarilah. Setiap api unggun butuh kayu baru.", "来い。焚き火にはいつも新しい薪がいる。", "오너라. 모든 모닥불엔 새 장작이 필요하지.", "來吧。每堆篝火都需要新柴。", "来吧。每堆篝火都需要新柴。"],

    # Yomi-hebi (Yomi)
    "dialog.yomi_hebi.open": ["Cada cabeça guarda alguém que se apagou. Quer ser a quarta?", "Each head keeps someone who went out. Want to be the fourth?", "Cada cabeza guarda a alguien que se apagó. ¿Quieres ser la cuarta?", "Jeder Kopf bewahrt jemanden, der erlosch. Willst du der vierte sein?", "Chaque tête garde quelqu'un qui s'est éteint. Tu veux être la quatrième ?", "Каждая голова хранит того, кто угас. Хочешь стать четвёртой?", "Tiap kepala menyimpan seseorang yang padam. Mau jadi yang keempat?", "頭はそれぞれ、消えた者を抱いている。四つ目になりたいか？", "머리마다 꺼져 간 누군가를 품고 있다. 네 번째가 되고 싶으냐?", "每顆頭都守著一個熄滅的人。想當第四個嗎？", "每颗头都守着一个熄灭的人。想当第四个吗？"],
    "dialog.yomi_hebi.reply.aki": ["Não. Ainda tenho alguém para buscar lá dentro.", "No. I still have someone to bring back from in there.", "No. Aún tengo a alguien que buscar ahí dentro.", "Nein. Dort drinnen muss ich noch jemanden holen.", "Non. J'ai encore quelqu'un à aller chercher là-dedans.", "Нет. Мне ещё нужно кое-кого оттуда забрать.", "Tidak. Masih ada seseorang yang harus kujemput di dalam sana.", "いいえ。まだ奥に迎えに行く人がいる。", "아니. 저 안에 아직 데려와야 할 사람이 있어.", "不。裡面還有人等我去接。", "不。里面还有人等我去接。"],
    "dialog.yomi_hebi.reply.kenta": ["Corto uma e nascem duas? Então corto rápido.", "Cut one and two grow back? Then I'll cut fast.", "¿Corto una y nacen dos? Entonces corto rápido.", "Schlag ich einen ab, wachsen zwei nach? Dann schlag ich schnell.", "J'en coupe une, il en pousse deux ? Alors je coupe vite.", "Отрубишь одну, вырастут две? Значит, руби быстрее.", "Potong satu, tumbuh dua? Kalau begitu aku memotong cepat.", "一つ斬れば二つ生える？なら速く斬るまでだ。", "하나 베면 둘이 자란다고? 그럼 빨리 베면 되지.", "砍一顆長兩顆？那我就砍快一點。", "砍一颗长两颗？那我就砍快一点。"],
    "dialog.yomi_hebi.reply.hana": ["Velas dos mortos se apagam com reverência, não com medo.", "Candles of the dead are put out with reverence, not fear.", "Las velas de los muertos se apagan con reverencia, no con miedo.", "Totenkerzen löscht man mit Ehrfurcht, nicht mit Angst.", "Les bougies des morts s'éteignent avec respect, pas avec peur.", "Свечи мёртвых гасят с почтением, а не со страхом.", "Lilin para arwah dipadamkan dengan hormat, bukan dengan takut.", "死者の灯は、恐れではなく敬いをもって消すもの。", "죽은 자의 촛불은 두려움이 아니라 공경으로 끄는 거야.", "亡者之燭要以敬意熄滅，而非恐懼。", "亡者之烛要以敬意熄灭，而非恐惧。"],
    "dialog.yomi_hebi.reply.goro": ["Eu devia ter morrido há cem anos. Não serei sua vela hoje.", "I should have died a hundred years ago. I won't be your candle today.", "Debí morir hace cien años. Hoy no seré tu vela.", "Ich hätte vor hundert Jahren sterben sollen. Heute werde ich nicht deine Kerze.", "J'aurais dû mourir il y a cent ans. Je ne serai pas ta bougie aujourd'hui.", "Мне следовало умереть сто лет назад. Сегодня я не стану твоей свечой.", "Seharusnya aku mati seratus tahun lalu. Hari ini aku tak akan jadi lilinmu.", "百年前に死んでいるはずの身。今日、お前の灯にはならん。", "백 년 전에 죽었어야 할 몸이오. 오늘 그대의 촛불이 되진 않겠소.", "我百年前就該死了。今天不會成為你的燭火。", "我百年前就该死了。今天不会成为你的烛火。"],
    "dialog.yomi_hebi.reply.rin": ["A vela do meu irmão ainda está acesa. E vai ficar.", "My brother's candle is still lit. And it will stay that way.", "La vela de mi hermano sigue encendida. Y así seguirá.", "Die Kerze meines Bruders brennt noch. Und so bleibt es.", "La bougie de mon frère brûle encore. Et elle le restera.", "Свеча моего брата ещё горит. И будет гореть.", "Lilin kakakku masih menyala. Dan akan tetap begitu.", "兄の灯はまだ消えてない。消させもしない。", "오빠의 촛불은 아직 켜져 있어. 앞으로도 그럴 거야.", "我哥哥的燭火還亮著。也會一直亮著。", "我哥哥的烛火还亮着。也会一直亮着。"],
    "dialog.yomi_hebi.reply.tora": ["Velho demais para ser vela. Não para segurar uma lanterna.", "Too old to be a candle. Not too old to hold a lantern.", "Demasiado viejo para ser vela. No para sostener una linterna.", "Zu alt, um eine Kerze zu sein. Nicht zu alt, eine Laterne zu halten.", "Trop vieux pour être une bougie. Pas pour tenir une lanterne.", "Слишком стар, чтобы быть свечой. Но не чтобы держать фонарь.", "Terlalu tua untuk jadi lilin. Tapi belum untuk memegang lentera.", "灯になるには年を取りすぎた。灯籠を持つにはまだ若い。", "촛불이 되기엔 너무 늙었지. 등불을 들기엔 아직 아니야.", "老得當不了燭火。卻還提得動燈籠。", "老得当不了烛火。却还提得动灯笼。"],
    "dialog.yomi_hebi.reply.yuki": ["Minha chama é meio sombra. Você não conseguiria apagá-la.", "My flame is half shadow. You couldn't put it out.", "Mi llama es mitad sombra. No podrías apagarla.", "Meine Flamme ist halb Schatten. Du könntest sie nicht löschen.", "Ma flamme est à moitié ombre. Tu ne pourrais pas l'éteindre.", "Моё пламя наполовину тень. Тебе его не погасить.", "Nyala apiku separuh bayangan. Kau tak akan bisa memadamkannya.", "私の炎は半分が影。あなたには消せない。", "내 불꽃은 반쯤 그림자야. 넌 끌 수 없어.", "我的火焰一半是影子。你熄不掉的。", "我的火焰一半是影子。你熄不掉的。"],
    "dialog.yomi_hebi.aside": ["Atrás dele está Ne-no-Kuni. Kuroe espera do outro lado.", "Beyond it lies Ne-no-Kuni. Kuroe waits on the other side.", "Tras ella está Ne-no-Kuni. Kuroe espera al otro lado.", "Dahinter liegt Ne-no-Kuni. Kuroe wartet auf der anderen Seite.", "Derrière lui se trouve Ne-no-Kuni. Kuroe attend de l'autre côté.", "За ним лежит Нэ-но-куни. Куроэ ждёт по ту сторону.", "Di baliknya ada Ne-no-Kuni. Kuroe menunggu di seberang.", "あやつの先に根の国がある。黒衛は向こう側で待っておる。", "그 너머에 뿌리의 나라가 있네. 쿠로에가 저편에서 기다리고 있어.", "牠身後是根之國。黑衛在另一邊等著。", "它身后是根之国。黑卫在另一边等着。"],
    "dialog.yomi_hebi.close": ["Então escolha qual das três vai te apagar.", "Then choose which of the three will snuff you out.", "Entonces elige cuál de las tres te apagará.", "Dann wähle, welcher der drei dich auslöscht.", "Alors choisis laquelle des trois va t'éteindre.", "Тогда выбирай, какая из трёх тебя погасит.", "Kalau begitu, pilih mana dari ketiganya yang akan memadamkanmu.", "ならば選べ。三つのうち、どれに消されたい？", "그렇다면 골라라. 셋 중 무엇이 너를 끌지.", "那就選吧，三顆之中由哪一顆熄滅你。", "那就选吧，三颗之中由哪一颗熄灭你。"],

    # Kinchō (Encosta dos Mortos)
    "dialog.kincho.open": ["Guardo a ponte para Tokoyo. Aposto que você nem sabe qual de mim é o verdadeiro.", "I guard the bridge to Tokoyo. I bet you can't even tell which of me is real.", "Guardo el puente al Tokoyo. Apuesto a que ni sabes cuál de mí es el verdadero.", "Ich bewache die Brücke nach Tokoyo. Wetten, du weißt nicht mal, welcher von mir echt ist?", "Je garde le pont vers le Tokoyo. Je parie que tu ne sais même pas lequel de moi est le vrai.", "Я стерегу мост в Токоё. Спорим, ты даже не знаешь, который из меня настоящий?", "Aku menjaga jembatan ke Tokoyo. Taruhan, kau bahkan tak tahu mana aku yang asli.", "常世への橋はこの俺が守る。どれが本物の俺か、わかるまい。", "나는 도코요로 가는 다리를 지킨다. 어느 쪽이 진짜 나인지 모를걸. 내기할까?", "我守著通往常世的橋。我賭你連哪個是真的我都分不出來。", "我守着通往常世的桥。我赌你连哪个是真的我都分不出来。"],
    "dialog.kincho.reply.aki": ["Não preciso saber. Basta a luz mostrar.", "I don't need to know. The light will show me.", "No necesito saberlo. Basta con que la luz lo muestre.", "Ich muss es nicht wissen. Das Licht zeigt es mir.", "Pas besoin de savoir. La lumière me le montrera.", "Мне не нужно знать. Свет покажет.", "Aku tak perlu tahu. Cukup cahaya yang menunjukkan.", "知らなくていい。光が教えてくれる。", "알 필요 없어. 빛이 보여 줄 테니까.", "我不需要知道。光會讓我看見。", "我不需要知道。光会让我看见。"],
    "dialog.kincho.reply.kenta": ["Mudar de forma? Faço isso desde criança.", "Shapeshifting? I've done that since I was a kid.", "¿Cambiar de forma? Lo hago desde niño.", "Gestaltwandeln? Das mach ich seit meiner Kindheit.", "Changer de forme ? Je fais ça depuis l'enfance.", "Менять облик? Я делаю это с детства.", "Berganti rupa? Aku sudah melakukannya sejak kecil.", "化ける？俺はガキの頃からやってる。", "둔갑? 난 어릴 때부터 해 왔어.", "變化形體？我從小就會。", "变化形体？我从小就会。"],
    "dialog.kincho.reply.hana": ["Uma miko reconhece um espírito pela sombra, não pela forma.", "A miko knows a spirit by its shadow, not its shape.", "Una miko reconoce a un espíritu por su sombra, no por su forma.", "Eine Miko erkennt einen Geist am Schatten, nicht an der Gestalt.", "Une miko reconnaît un esprit à son ombre, pas à sa forme.", "Мико узнаёт духа по тени, а не по облику.", "Seorang miko mengenali roh dari bayangannya, bukan rupanya.", "巫女は霊を姿ではなく影で見分けるもの。", "무녀는 영을 모습이 아니라 그림자로 알아봐.", "巫女看影子辨識靈體，而不是看外形。", "巫女看影子辨识灵体，而不是看外形。"],
    "dialog.kincho.reply.goro": ["Não aposto, tanuki. Votos são minha única moeda.", "I don't gamble, tanuki. Vows are my only coin.", "No apuesto, tanuki. Los votos son mi única moneda.", "Ich wette nicht, Tanuki. Gelübde sind meine einzige Münze.", "Je ne parie pas, tanuki. Les vœux sont ma seule monnaie.", "Я не бьюсь об заклад, тануки. Обеты — моя единственная монета.", "Aku tak bertaruh, tanuki. Sumpah adalah satu-satunya uangku.", "賭けはせん、狸よ。拙僧の銭は誓いだけだ。", "내기는 하지 않소, 너구리. 서원만이 내 유일한 동전이오.", "我不賭，狸貓。誓願是我唯一的錢幣。", "我不赌，狸猫。誓愿是我唯一的钱币。"],
    "dialog.kincho.reply.rin": ["Aposto o amanhecer. É tudo o que tenho.", "I bet the dawn. It's all I have.", "Apuesto el amanecer. Es todo lo que tengo.", "Ich setze die Morgendämmerung. Mehr habe ich nicht.", "Je parie l'aube. C'est tout ce que j'ai.", "Ставлю рассвет. Это всё, что у меня есть.", "Aku pertaruhkan fajar. Hanya itu yang kupunya.", "夜明けを賭ける。私にはそれしかない。", "새벽을 걸게. 내가 가진 건 그것뿐이야.", "我賭上黎明。那是我僅有的。", "我赌上黎明。那是我仅有的。"],
    "dialog.kincho.reply.tora": ["Tanuki apostam, ferreiros martelam. Vamos ver quem cansa antes.", "Tanuki bet, smiths hammer. Let's see who tires first.", "Los tanuki apuestan, los herreros martillan. Veamos quién se cansa antes.", "Tanuki wetten, Schmiede hämmern. Mal sehen, wer zuerst müde wird.", "Les tanuki parient, les forgerons martèlent. Voyons qui se lasse le premier.", "Тануки спорят, кузнецы куют. Посмотрим, кто устанет первым.", "Tanuki bertaruh, pandai besi menempa. Kita lihat siapa yang lelah duluan.", "狸は賭け、鍛冶屋は槌を振る。どっちが先にへばるかな。", "너구리는 내기를 하고 대장장이는 망치질을 하지. 누가 먼저 지치나 보세.", "狸貓下注，鐵匠打鐵。看誰先累。", "狸猫下注，铁匠打铁。看谁先累。"],
    "dialog.kincho.reply.yuki": ["Também sou duas coisas ao mesmo tempo. Hoje escolho ser uma só.", "I'm two things at once too. Today I choose to be just one.", "Yo también soy dos cosas a la vez. Hoy elijo ser solo una.", "Auch ich bin zwei Dinge zugleich. Heute wähle ich, nur eins zu sein.", "Moi aussi, je suis deux choses à la fois. Aujourd'hui, je choisis d'en être une seule.", "Я тоже две сущности сразу. Сегодня я выбираю быть одной.", "Aku juga dua hal sekaligus. Hari ini aku memilih jadi satu saja.", "私も二つを同時に生きている。今日は一つを選ぶ。", "나도 두 가지가 한 몸에 있어. 오늘은 하나만 고를래.", "我也同時是兩種存在。今天我選擇只做一個。", "我也同时是两种存在。今天我选择只做一个。"],
    "dialog.kincho.aside": ["Os tambores vêm do outro lado da ponte. Izanami está perto.", "The drums come from across the bridge. Izanami is near.", "Los tambores vienen del otro lado del puente. Izanami está cerca.", "Die Trommeln kommen von jenseits der Brücke. Izanami ist nah.", "Les tambours viennent de l'autre côté du pont. Izanami est proche.", "Барабаны звучат из-за моста. Идзанами близко.", "Genderang datang dari seberang jembatan. Izanami sudah dekat.", "太鼓は橋の向こうから聞こえる。伊邪那美は近い。", "북소리는 다리 건너편에서 들려오네. 이자나미가 가까이 있어.", "鼓聲來自橋的另一端。伊邪那美就在附近。", "鼓声来自桥的另一端。伊邪那美就在附近。"],
    "dialog.kincho.close": ["Aposta aceita! Se perder, sua lanterna é minha.", "Bet accepted! If you lose, your lantern is mine.", "¡Apuesta aceptada! Si pierdes, tu linterna es mía.", "Wette angenommen! Verlierst du, gehört deine Laterne mir.", "Pari tenu ! Si tu perds, ta lanterne est à moi.", "Ставка принята! Проиграешь — твой фонарь мой.", "Taruhan diterima! Kalau kalah, lenteramu milikku.", "賭け成立！負けたらその灯籠は俺のものだ。", "내기 성립! 지면 네 등불은 내 거다.", "賭局成立！你輸了，燈籠就歸我。", "赌局成立！你输了，灯笼就归我。"],
}
